Ltac mono_case :=
  lazymatch goal with
  | |- tle (match ?c with _ => _ end) _ => destruct c
  end.

Ltac mono_auto cal :=
  first [ apply tle_refl
        | cal
        | (apply tle_vis; intros ?); mono_auto cal
        | mono_case; mono_auto cal
        | progress (cbv zeta); mono_auto cal ].
